void can_usr_rx_reg_fast( Can_Dev_Id dev_id , Reg_Func rx_fast_func )
{
    reg_func( can_usr[dev_id].rx_reg_fast , 0 , rx_fast_func );
}

//--------------------------------------------------------------------------//

void can_usr_rx_reg_slow ( Can_Dev_Id dev_id ,  Reg_Func rx_slow_func , UInt32 can_id )
{
	
	can_usr_rx_filter_add( dev_id,can_id);
    
    reg_func( can_usr[dev_id].rx_reg_slow , (Reg_Id)can_id , rx_slow_func );
}

